import {GRADES,LESSONS,QUESTIONS,SOURCE_URL,isCorrect,gradeLabel,lessonById} from './data.js';
import {readState,writeState,localDay,stats,latestAttempts,putFile,getFile} from './storage.js?v=local6';
import {makeWorksheet,downloadBlob,safeFilename,printPages} from './pdf.js';
import {exactAnswer} from './answer-checker.js';
import {createPaperStudy} from './paper-study.js?v=local6';
import {paginate} from './paper-model.js?v=local6';
import {loadHmeCatalog,currentCatalog,cachedHmeQuestions,loadHmePaper,getCachedHmePaper,drawHmePage,hmeQuestionRaster,hmeSourceUrl,getHmeBytes} from './hme.js?v=local6';

const app=document.querySelector('#app'),modalRoot=document.querySelector('#modal-root');
let state=readState(),filters={search:'',lesson:'all',difficulty:'all',status:'all'},toastTimer,returnFocus;
let studyUI={id:null,hint:false,result:null,answer:'',scratch:''},lessonResult=null,examIndex=0,examResult=null,examDraft='',objectUrl=null,renderSequence=0;
let worksheet={title:'나만의 수학 학습지',includeAnswers:true,space:'normal'},busy=false;
let activePdf=null,pdfId=null,pdfPage=1,pdfZoom=1,pdfRenderTask=null,pdfLibraryPromise=null;
let bankOrigin='hme',bankPaperId='',hmeYear='all',hmeOnlyChecked=false,hmeLimit=12,hmeDocKind='paper',hmeDocPage=1,hmeDocPages=1,renderedHmeQuestion=null;
let hmeZoom=1;
const hmeRequests=new Set();
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',book:'M12 5v16M12 5C8 2 3 4 3 4v15s5-2 9 2c4-4 9-2 9-2V4s-5-2-9 1Z',layers:'m12 3 10 6-10 6L2 9l10-6Zm-9 11 9 5 9-5M3 18l9 5 9-5',file:'M14 2H5v20h14V7l-5-5Zm0 0v6h5M8 12h8M8 16h6',review:'M5 8a8 8 0 1 1-1 8M2 3v6h6M12 8v5l3 2',printer:'M6 8V2h12v6M6 17H3V8h18v9h-3M6 14h12v8H6zM17 11h1',help:'M9.5 8a2.5 2.5 0 1 1 4 2c-1 .7-1.5 1-1.5 3M12 17h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',back:'M20 12H4m6-6-6 6 6 6',search:'m16 16 5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',settings:'m9 3 1-2h4l1 2 3 2 2 .3 2 3-1 2v3l1 2-2 3-2 .3-3 2-1 2h-4l-1-2-3-2-2-.3-2-3 1-2v-3l-1-2 2-3L6 5l3-2Zm7 9a4 4 0 1 1-8 0 4 4 0 0 1 8 0',calendar:'M3 5h18v17H3zM7 2v6M17 2v6M3 11h18',check:'m5 12 4 4L19 6',target:'M21 12a9 9 0 1 1-9-9M17 12a5 5 0 1 1-5-5M12 12l9-9M17 3h4v4',flame:'M13 2c2 6-4 7-2 11 2-1 3-2 4-4 5 4 5 11-2 13-10 0-11-9-6-14 0 4 3 4 3 1 0-3 1-5 3-7Z',sparkles:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7ZM20 2v4M18 4h4',calculator:'M5 2h14v20H5zM8 6h8M8 10h1M15 10h1M8 14h1M15 14h1M8 18h1M15 18h1',shapes:'m7 3 5 9H2l5-9Zm7 10h8v8h-8zM10 18a4 4 0 1 1-8 0 4 4 0 0 1 8 0',pie:'M12 2v10h10A10 10 0 1 1 12 2Zm4 0v6h6a8 8 0 0 0-6-6',ratio:'m5 20 14-16M8 6a2 2 0 1 1-4 0 2 2 0 0 1 4 0Zm12 12a2 2 0 1 1-4 0 2 2 0 0 1 4 0',network:'M12 3v7M5 10h14M5 10v6M19 10v6M9 1h6v4H9zM2 17h6v5H2zM16 17h6v5h-6z',function:'M18 3c-3-2-5 0-6 4l-2 10c-1 4-3 6-6 4M6 9h12',chart:'M3 3v18h19M6 16l5-6 4 3 6-9',download:'M12 2v14m-5-5 5 5 5-5M3 17v5h18v-5',upload:'M12 17V3m-5 5 5-5 5 5M3 17v5h18v-5',plus:'M12 4v16M4 12h16',close:'m6 6 12 12M6 18 18 6',external:'M14 3h7v7m0-7L11 13M10 3H3v18h18v-7',bookmark:'M6 3h12v19l-6-4-6 4V3Z',clock:'M12 7v6l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',info:'M12 11v6M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',menu:'M3 6h18M3 12h18M3 18h18',edit:'m16 3 5 5L8 21H3v-5L16 3ZM13 6l5 5',leaf:'M20 3C8 1 1 9 5 16c7 5 16-2 15-13ZM4 21 17 7'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.book}"/></svg>`;
const allQuestions=()=>[...new Map([...QUESTIONS,...state.custom,...(state.officialCache||[]),...cachedHmeQuestions()].map(q=>[q.id,q])).values()];
const getQuestion=id=>allQuestions().find(q=>q.id===id);
const route=()=>{const parts=location.hash.slice(1).split('/');return {page:parts[0]||'home',id:parts[1]||''};};
const go=path=>{if(location.hash==='#'+path)render();else location.hash=path;};
const save=()=>{try{writeState(state);}catch{toast('저장 공간이 부족합니다. 학습 기록을 내보낸 뒤 브라우저 저장 공간을 확인해 주세요.');}};
function toast(message){const node=document.querySelector('#toast');clearTimeout(toastTimer);node.textContent=message;node.classList.add('visible');toastTimer=setTimeout(()=>node.classList.remove('visible'),4200);}
const difficulty=n=>['기본','도전','심화'][n-1]||'도전';
const tag=(text,color='')=>`<span class="tag ${color}">${esc(text)}</span>`;
const button=(label,action,style='primary',ico='arrow',extra='')=>`<button class="btn ${style}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;
function intro(title,description,action=''){return `<div class="page-intro"><div><div class="eyebrow">THINK DEEPER, GROW TOGETHER</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function shell(content){
 const r=route();const navPage=r.page==='solve'?'questions':r.page==='lesson'?'concepts':['exam','hme','answers','hme-document'].includes(r.page)?'archive':r.page;
 const links=[['home','home','학습 홈'],['concepts','book','개념 학습'],['questions','layers','문제 풀기'],['archive','file','기출 자료실'],['review','review','나의 오답노트'],['worksheet','printer','학습지 만들기']];
 return `<div class="app-shell"><aside class="sidebar" aria-label="주 메뉴"><a class="brand" href="#home"><span class="brand-mark"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="m5 25 11-20 12 20H5Z" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="21" cy="23" r="8" fill="currentColor" opacity=".65"/></svg></span>생각수학</a><div class="brand-sub">생각하는 힘, 자라는 실력</div><div class="nav-label">MY LEARNING</div><nav class="nav">${links.map(([id,ico,label])=>`<a href="#${id}" class="nav-link ${navPage===id?'active':''}" ${navPage===id?'aria-current="page"':''}>${icon(ico)}${label}</a>`).join('')}</nav><div class="nav-separator"></div><button class="nav-link" style="border:0;background:transparent" data-action="help">${icon('help')}학습 가이드</button><div class="sidebar-tip">${icon('file')}<h3>나만의 문제집, 한 권 뚝딱</h3><p>필요한 문제만 모아서<br>PDF로 저장하고 인쇄해요.</p><button data-action="go" data-path="worksheet">학습지 만들기 ${icon('arrow')}</button></div><div class="sidebar-footer"><span class="status-dot"></span>이 기기에 학습 기록을 저장해요</div></aside><div class="workspace"><header class="topbar"><button class="icon-button mobile-menu" data-action="menu" aria-label="메뉴 열기">${icon('menu')}</button><div class="breadcrumb">나의 학습 공간 ${icon('chevron')}<strong>${links.find(l=>l[0]===navPage)?.[2]||'생각수학'}</strong></div><div class="top-actions"><label class="grade-select">${icon('book')}<select id="global-grade" aria-label="학습 학년">${GRADES.map((g,i)=>`<option value="${i+1}" ${state.grade===i+1?'selected':''}>${g}</option>`).join('')}</select></label><span class="top-divider"></span><button class="icon-button" data-action="search" aria-label="문제 검색">${icon('search')}</button><button class="icon-button" data-action="settings" aria-label="학습 설정">${icon('settings')}</button><button class="profile-button" data-action="settings" aria-label="${esc(state.name)} 프로필 설정"><span class="avatar">${esc(state.name.slice(0,1))}</span><span class="profile-name">${esc(state.name)} 님</span></button></div></header><main id="main" class="main page-enter" tabindex="-1">${content}<footer class="footer"><span>© ${new Date().getFullYear()} 생각수학 · 스스로 생각하는 즐거움</span><span>HME 공식 기출과 창작 연습문제를 구분해 제공합니다.　<a href="${SOURCE_URL}" target="_blank" rel="noopener noreferrer">HME 공식 기출 자료실 ${icon('external')}</a></span></footer></main></div></div>`;
}
function art(){return `<div class="hero-art" aria-hidden="true"><svg viewBox="0 0 440 290"><defs><filter id="shadow"><feDropShadow dx="0" dy="8" stdDeviation="8" flood-color="#526d3b" flood-opacity=".08"/></filter></defs><g transform="translate(35 16) rotate(-9 190 135)" filter="url(#shadow)"><path d="M110 187 201 37 292 187Z" fill="#d7e5b6" fill-opacity=".5" stroke="#88a16b" stroke-width="1.5"/><path d="M155 112 247 112 201 187Z" fill="#b6cb8b" fill-opacity=".55" stroke="#8ea672" stroke-width="1.2"/><path d="M201 37v150M110 187l137-75M292 187 155 112" fill="none" stroke="#a4b78b" stroke-width=".8" stroke-dasharray="4 5"/><circle cx="270" cy="172" r="63" fill="#ebedc5" fill-opacity=".55" stroke="#8ca075" stroke-width="1.5"/><circle cx="270" cy="172" r="43" fill="none" stroke="#a6b38d" stroke-width=".8"/><path d="M270 109v126M207 172h126" fill="none" stroke="#b9c49f" stroke-width=".8"/><circle cx="110" cy="187" r="3" fill="#647e51"/><circle cx="201" cy="37" r="3" fill="#647e51"/><circle cx="292" cy="187" r="3" fill="#647e51"/><text x="193" y="25" font-size="16" fill="#8ca175" font-family="Georgia" font-style="italic">A</text><text x="92" y="208" font-size="16" fill="#8ca175" font-family="Georgia" font-style="italic">B</text><text x="300" y="204" font-size="16" fill="#8ca175" font-family="Georgia" font-style="italic">C</text></g><text x="38" y="91" transform="rotate(-12 38 91)" fill="#9bad84" font-family="Georgia" font-style="italic" font-size="26">a² + b²</text><text x="290" y="55" transform="rotate(8 290 55)" fill="#a4b287" font-family="Georgia" font-style="italic" font-size="29">×</text><text x="70" y="249" fill="#a5b78c" font-family="Georgia" font-size="22">½</text><path d="M348 224v16m-8-8h16M90 40v12m-6-6h12" stroke="#acbb93" stroke-width="1.4"/></svg><span class="art-tag">이해하는 순간, 수학이 재미있어져요.</span></div>`;}
function conceptCard(lesson,large=false){const completed=state.checkedLessons.includes(lesson.id);return `<button class="concept-card" data-action="go" data-path="lesson/${lesson.id}"><span class="concept-icon ${lesson.color}">${icon(lesson.icon)}</span><h3>${lesson.title}</h3><p>${lesson.subtitle}</p><div class="concept-card-bottom"><span>${completed?'개념 확인 완료':'원리부터 차근차근'}</span>${icon(completed?'check':'arrow')}</div></button>`;}
function home(){
 const s=stats(state.attempts),today=localDay(),base=new Date();
 const week=Array.from({length:7},(_,i)=>{const d=new Date(base);d.setDate(base.getDate()-(6-i));const day=localDay(d);return {day,label:new Intl.DateTimeFormat('ko-KR',{weekday:'short',timeZone:'Asia/Seoul'}).format(d),done:state.attempts.some(a=>a.day===day)};});
 return `${intro(`반가워요, ${esc(state.name)} 님 <span style="font-size:20px">☀</span>`,'오늘도 한 걸음, 수학과 조금 더 가까워져요.',`<div class="date-pill">${icon('calendar')}${new Intl.DateTimeFormat('ko-KR',{month:'long',day:'numeric',weekday:'long',timeZone:'Asia/Seoul'}).format(base)}</div>`)}<section class="hero"><div class="hero-copy"><span class="small-pill">${icon('leaf')} 개념부터 탄탄하게</span><h2>작은 질문이,<br><span>큰 실력</span>이 되는 곳.</h2><p>외우는 수학에서 이해하는 수학으로.<br>원리를 발견하고, 문제를 풀며 생각의 힘을 키워요.</p><div class="button-row">${button('오늘의 학습 시작','start','primary','arrow')}${button('개념 둘러보기','go','ghost','', 'data-path="concepts"')}</div></div>${art()}</section><section class="stats" aria-label="나의 학습 현황"><div class="stat"><span class="stat-icon">${icon('edit')}</span><div><div class="stat-label">차곡차곡 푼 문제</div><div class="stat-number">${s.solved}<small>문제</small></div></div><span class="stat-aside">한 문제씩 쌓아가요</span></div><div class="stat"><span class="stat-icon">${icon('target')}</span><div><div class="stat-label">나의 정답률</div><div class="stat-number">${s.accuracy===null?'—':s.accuracy}<small>%</small></div></div><span class="stat-aside">모든 채점 기록 기준</span></div><div class="stat"><span class="stat-icon">${icon('flame')}</span><div><div class="stat-label">함께 공부한 날</div><div class="stat-number">${s.days}<small>일</small></div></div><span class="stat-aside">꾸준함이 실력이 돼요</span></div></section><div class="dashboard-grid"><div><div class="section-heading"><div><h2>오늘은 여기서 시작해요 ${icon('sparkles')}</h2><p>개념 하나를 이해하면, 풀 수 있는 문제가 늘어나요.</p></div></div><article class="recommend-card"><div class="fraction-visual"><div class="fraction-grid">${Array.from({length:8},(_,i)=>`<span class="${i<3?'filled':''}"></span>`).join('')}</div><div class="fraction-caption">3 / 8</div></div><div class="recommend-copy"><div class="tags">${tag('추천 개념')}${tag('분수와 소수','gray')}</div><h3>같은 크기로 나누면,<br>분수가 보이기 시작해요.</h3><p>전체와 부분의 관계를 그림으로 이해해 봐요.</p><div class="recommend-footer"><span class="dots">${icon('clock')} 약 5분 · 개념 + 확인 문제</span><button class="round-arrow" data-action="go" data-path="lesson/fractions" aria-label="분수 개념 학습 시작">${icon('arrow')}</button></div></div></article><div class="section-heading"><h2>생각의 기초, 개념 학습</h2><button class="text-button" data-action="go" data-path="concepts">전체 보기 ${icon('chevron')}</button></div><div class="concept-grid">${LESSONS.slice(0,6).map(l=>conceptCard(l)).join('')}</div></div><aside class="dashboard-aside"><div class="aside-card"><h3>오늘의 작은 목표</h3><p class="muted">매일 조금씩, 나만의 속도로.</p><div class="goal-value"><strong>${s.today}</strong><span>/ ${state.dailyGoal}문제</span></div><div class="progress" role="progressbar" aria-label="오늘의 문제 풀이 목표" aria-valuemin="0" aria-valuemax="${state.dailyGoal}" aria-valuenow="${Math.min(s.today,state.dailyGoal)}"><span style="width:${Math.min(s.today/state.dailyGoal*100,100)}%"></span></div><div class="goal-note">${icon('leaf')}${s.today>=state.dailyGoal?'오늘 목표를 달성했어요!':'한 문제의 이해가 큰 변화를 만들어요.'}</div></div><div class="aside-card"><h3>나의 학습 발자국</h3><p class="muted">최근 7일의 도전을 기록해요.</p><div class="weekly">${week.map(d=>`<div class="week-day">${d.label}<span class="week-dot ${d.day===today?'today':''} ${d.done?'done':''}" title="${d.day} ${d.done?'학습 완료':'기록 없음'}">${d.done?icon('check'):d.day===today?'·':''}</span></div>`).join('')}</div></div><div class="aside-card archive-callout">${icon('file')}<h3>기출문제로 실전 감각 쌓기</h3><p>HME 공식 자료실의 기출 PDF를<br>등록하고 차근차근 풀어 보세요.</p><button class="text-button" data-action="go" data-path="archive">기출 자료실로 가기 ${icon('arrow')}</button></div></aside></div>`;
}
function concepts(){return `${intro('이해하는 순간, 내 것이 되는 개념','계산보다 먼저 원리를, 정답보다 먼저 생각을 배워요.')}<div class="lesson-library">${LESSONS.map(l=>conceptCard(l,true)).join('')}</div>`;}
function lessonPage(id){const l=LESSONS.find(l=>l.id===id);if(!l)return emptyPage('개념을 찾을 수 없어요.','concepts');return `<div class="lesson-detail">${button('개념 목록','go','ghost back-button','back','data-path="concepts"')}<article class="panel"><span class="concept-icon ${l.color}">${icon(l.icon)}</span>${tag('개념 학습')}<h1>${l.title}</h1><p class="lesson-lead">${l.lead}</p><p class="lesson-text">${l.body}</p>${id==='fractions'?`<div class="fraction-demo"><div class="fraction-grid" id="fraction-demo">${Array.from({length:8},(_,i)=>`<button class="${i<3?'':'off'}" data-action="fraction" aria-pressed="${i<3}" aria-label="${i+1}번째 조각 선택">${i+1}</button>`).join('')}</div><span class="fraction-display" id="fraction-display">3 / 8</span><span class="muted" style="font-size:11px">조각을 눌러 분수를 바꿔 보세요.</span></div>`:''}<div class="formula-card"><h3>${l.principle}</h3><div class="formula">${l.formula}</div><p class="formula-example">${l.example}</p></div><h3 style="font-size:15px">한 단계씩 이해해요</h3><ol class="solution-list">${l.steps.map((s,i)=>`<li><span class="step-num">${i+1}</span><span>${s}</span></li>`).join('')}</ol><div class="lesson-warning">${icon('info')} <strong>여기서 잠깐!</strong> ${l.pitfall}</div><div class="check-panel"><h3>이해했는지 확인해 볼까요?</h3><p>${l.check.text}</p><form id="lesson-answer" class="answer-form"><input aria-label="개념 확인 문제 답" name="answer" placeholder="답을 적어 보세요" required autocomplete="off">${button('확인하기','lesson-submit','primary','check','type="submit"')}</form>${lessonResult?`<div class="result ${lessonResult.correct?'':'wrong'}"><h3>${lessonResult.correct?'개념을 이해했어요!':'다시 생각해 볼까요?'}</h3><p>${l.check.explain}</p></div>`:''}</div><div class="button-row" style="margin-top:25px">${button('관련 문제 풀기','lesson-practice','primary','arrow',`data-id="${l.id}"`)}${button('다른 개념 보기','go','secondary','','data-path="concepts"')}</div></article></div>`;}
function filteredQuestions(){const latest=latestAttempts(state.attempts);return allQuestions().filter(q=>q.grade===state.grade).filter(q=>filters.lesson==='all'||q.lesson===filters.lesson).filter(q=>filters.difficulty==='all'||q.difficulty===Number(filters.difficulty)).filter(q=>filters.status==='all'||(filters.status==='unseen'&&!latest.has(q.id))||(filters.status==='saved'&&state.bookmarks.includes(q.id))).filter(q=>`${q.title} ${q.text} ${lessonById(q.lesson).title}`.toLowerCase().includes(filters.search.toLowerCase()));}
function questionRow(q,review=false){const last=latestAttempts(state.attempts).get(q.id);return `<article class="question-row"><input type="checkbox" aria-label="${esc(q.title)} 학습지에 추가" data-select="${esc(q.id)}" ${state.selected.includes(q.id)?'checked':''}><div class="question-content"><div class="tags">${tag(gradeLabel(q.grade),'gray')}${tag(lessonById(q.lesson).title)}${tag(q.origin==='hme'?'HME 공식 기출':q.origin==='created'?'창작 연습':'직접 등록','gray')}<span class="difficulty" aria-label="난이도 ${difficulty(q.difficulty)}">${'●'.repeat(q.difficulty)}${'○'.repeat(3-q.difficulty)}</span>${last?tag(last.correct?'풀이 완료':'복습 필요',last.correct?'':'peach'):''}</div><h3>${esc(q.title)}</h3><p>${q.origin==='hme'?'공식 원문 도형·수식 보존 · 정답표 대조 완료':esc(q.text)}</p></div><div class="question-row-actions"><button class="icon-button" data-action="bookmark" data-id="${esc(q.id)}" aria-label="${state.bookmarks.includes(q.id)?'북마크 해제':'북마크 추가'}" aria-pressed="${state.bookmarks.includes(q.id)}" style="color:${state.bookmarks.includes(q.id)?'#8ca967':'#c0c8b7'}">${icon('bookmark')}</button>${button(review?'다시 풀기':'풀어보기','go','secondary small','arrow',`data-path="solve/${esc(q.id)}"`)}</div></article>`;}
function practiceQuestionsPage(){const questions=filteredQuestions();return `${intro('한 문제씩, 생각의 힘을 키워요',`${gradeLabel(state.grade)} · 직접 풀고 이해하는 연습문제`,button('문제 등록','custom','secondary','plus'))}<div class="toolbar"><label class="search-box">${icon('search')}<input type="search" id="question-search" aria-label="문제 검색" placeholder="문제나 개념을 검색해 보세요" value="${esc(filters.search)}"></label><select class="field-control" id="filter-lesson" aria-label="개념 필터"><option value="all">모든 개념</option>${LESSONS.map(l=>`<option value="${l.id}" ${filters.lesson===l.id?'selected':''}>${l.title}</option>`).join('')}</select><select class="field-control" id="filter-difficulty" aria-label="난이도 필터"><option value="all">모든 난이도</option>${[1,2,3].map(n=>`<option value="${n}" ${Number(filters.difficulty)===n?'selected':''}>${difficulty(n)}</option>`).join('')}</select></div><div class="filter-tabs">${[['all','전체 문제'],['unseen','아직 안 푼 문제'],['saved','북마크']].map(([id,title])=>`<button data-action="status-filter" data-id="${id}" class="${filters.status===id?'active':''}">${title}</button>`).join('')}</div><div class="list-meta"><span>총 <strong>${questions.length}</strong>문제</span><button class="text-button" data-action="go" data-path="worksheet">${icon('printer')} 선택한 문제 ${state.selected.length}개로 학습지 만들기 ${icon('arrow')}</button></div><div class="question-list" id="question-list">${questions.length?questions.map(q=>questionRow(q)).join(''):empty('search','조건에 맞는 문제가 없어요.','학년이나 필터를 바꾸거나 직접 문제를 등록해 보세요.',button('필터 초기화','reset-filters','secondary','review'))}</div><p class="muted" style="font-size:10px;margin-top:20px">기본 수록 ${QUESTIONS.length}문항은 개념 학습을 위해 직접 만든 연습문제입니다. HME 기출 원문은 기출 자료실에서 PDF로 등록할 수 있어요.</p>`;}
function empty(ico,title,message,action=''){return `<div class="empty">${icon(ico)}<h3>${title}</h3><p>${message}</p>${action}</div>`;}
function emptyPage(message,target='home'){return empty('search',message,'메뉴에서 다시 시작해 주세요.',button('돌아가기','go','primary','back',`data-path="${target}"`));}
function practiceSolvePage(id){const q=getQuestion(id);if(!q)return emptyPage('문제를 찾을 수 없어요.','questions');if(studyUI.id!==id)studyUI={id,hint:false,result:null,answer:'',scratch:''};const lesson=lessonById(q.lesson);const result=studyUI.result;return `${button('문제 목록','go','ghost back-button','back','data-path="questions"')}<div class="study-layout"><article class="panel question-panel"><div class="question-top"><div class="tags">${tag(gradeLabel(q.grade),'gray')}${tag(lesson.title)}${tag(difficulty(q.difficulty),'peach')}</div><span class="question-number">${q.origin==='created'?'창작 연습문제':'직접 등록한 문제'}</span></div><h2>${esc(q.title)}</h2><p class="question-body">${esc(q.text)}</p><label class="field-label" for="scratch">나의 생각 정리</label><textarea id="scratch" class="work-area" placeholder="어떤 원리를 사용할 수 있을까요? 자유롭게 풀이를 적어 보세요.">${esc(studyUI.scratch)}</textarea><form id="study-answer" class="answer-form"><label for="study-input">나의 답</label><input id="study-input" name="answer" value="${esc(studyUI.answer)}" placeholder="답을 입력하세요" required autocomplete="off"><span class="answer-unit">${esc(q.unit||'')}</span>${button('채점하기','submit-answer','primary','check','type="submit"')}</form><div class="button-row" style="margin-top:16px">${button(studyUI.hint?'힌트 닫기':'힌트가 필요해요','hint','ghost small','sparkles')}${button('학습지에 담기','add-question','ghost small','plus',`data-id="${esc(q.id)}"`)}</div>${studyUI.hint?`<div class="hint-box">${icon('sparkles')} ${esc(q.hint||'주어진 조건을 하나씩 정리하고 관련 개념을 떠올려 보세요.')}</div>`:''}${result?`<div class="result ${result.correct?'':'wrong'}" role="status"><h3>${result.correct?'잘했어요! 원리를 이해했네요.':'괜찮아요. 생각을 한 번 더 이어가요.'}</h3><p>${result.correct?'정답이에요. 아래 풀이와 나의 생각을 비교해 보세요.':`입력한 답: ${esc(result.answer)} · 정답: ${esc(q.answer)} ${esc(q.unit||'')}. 오답노트에 기록했어요.`}</p><ol class="solution-list">${(q.steps?.length?q.steps:['등록된 해설이 없습니다. 관련 개념을 확인하며 풀이를 정리해 보세요.']).map((s,i)=>`<li><span class="step-num">${i+1}</span><span>${esc(s)}</span></li>`).join('')}</ol><div class="button-row" style="margin-top:20px">${button(result.correct?'다음 문제 풀기':'다시 도전하기',result.correct?'next-question':'retry','primary small','arrow',`data-id="${esc(q.id)}"`)}${button('관련 개념 보기','go','secondary small','book',`data-path="lesson/${q.lesson}"`)}</div></div>`:''}</article><aside class="study-side"><div class="aside-card"><span class="concept-icon ${lesson.color}">${icon(lesson.icon)}</span><h3>문제 속 원리 찾기</h3><p>${lesson.title} 개념과 연결되는 문제예요. 막히는 부분이 있다면 원리로 돌아가 보세요.</p>${button('개념 다시 보기','go','secondary','book',`data-path="lesson/${lesson.id}"`)}</div><div class="aside-card"><h3>답보다 중요한, 나의 생각</h3><p>① 구해야 할 것을 찾아요.<br>② 조건을 그림이나 식으로 정리해요.<br>③ 답을 원래 조건에 넣어 확인해요.</p></div></aside></div>`;}
function reviewPage(){const latest=latestAttempts(state.attempts);const wrong=allQuestions().filter(q=>latest.get(q.id)?.correct===false);const resolved=allQuestions().filter(q=>latest.get(q.id)?.correct===true && state.attempts.some(a=>a.questionId===q.id&&!a.correct));const examWrong=state.attempts.filter(a=>a.examId&&latest.get(a.questionId)===a&&!a.correct);return `${intro('틀린 문제는, 다음 성장의 시작','헷갈렸던 원리를 돌아보고 나의 생각을 다시 완성해요.')}<div class="review-summary">${tag(`복습할 문제 ${wrong.length+examWrong.length}개`,'peach')}${tag(`다시 풀어 해결한 문제 ${resolved.length}개`)}</div>${wrong.length||examWrong.length?`<div class="question-list">${wrong.map(q=>questionRow(q,true)).join('')}${examWrong.map(a=>{const exam=state.exams.find(e=>e.id===a.examId);return exam?`<article class="question-row">${icon('file')}<div class="question-content"><div class="tags">${tag('등록한 PDF','gray')}${tag(`${a.index+1}번`,'peach')}</div><h3>${esc(exam.title)}</h3><p>기출 원문에서 문제를 다시 확인해 보세요.</p></div>${button('다시 풀기','exam-review','secondary small','arrow',`data-id="${esc(exam.id)}" data-index="${a.index}"`)}</article>`:'';}).join('')}</div>`:empty('leaf','차근차근 쌓이는 나의 오답노트','문제를 풀고 틀린 문제를 발견하면 여기에 모아 드릴게요. 다시 맞힌 문제는 해결한 문제로 옮겨져요.',button('문제 풀러 가기','go','primary','arrow','data-path="questions"'))}${resolved.length?`<div class="review-resolved"><div class="section-heading"><h2>다시 생각해서 해결했어요 ${icon('check')}</h2></div><div class="question-list">${resolved.map(q=>questionRow(q,true)).join('')}</div></div>`:''}`;}
function uploadedArchivePage(){return `${intro('기출문제로 준비하는 나의 다음 도전','공식 자료실에서 받은 PDF를 등록하고 온라인으로 풀어 보세요.',button('기출 PDF 등록','import-pdf','primary','upload'))}<div class="notice">${icon('info')}<div><strong>HME 공식 기출문제는 천재교육 로그인이 필요해요.</strong><br><a href="${SOURCE_URL}" target="_blank" rel="noopener noreferrer">공식 자료실 열기 ${icon('external')}</a>에서 직접 받은 PDF를 등록하세요. 원본을 보며 답안을 기록하고, 정답표가 있으면 자동으로 채점해요. 등록한 파일은 이 브라우저에 보관돼요.</div></div>${state.exams.length?`<div class="exam-grid">${state.exams.map(e=>`<article class="exam-card"><div class="file-icon">PDF</div><div class="tags">${tag(gradeLabel(e.grade),'gray')}${tag(e.answers.some(Boolean)?'정답 등록':'스스로 채점',e.answers.some(Boolean)?'':'peach')}</div><h3>${esc(e.title)}</h3><p>${esc(e.year)}년 · ${esc(e.semester)} · ${e.count}문제<br>${esc(e.filename)}</p><div class="button-row">${button('학습 시작','open-exam','primary small','arrow',`data-id="${esc(e.id)}"`)}${button('원본 PDF','download-exam','secondary small','download',`data-id="${esc(e.id)}"`)}</div></article>`).join('')}</div>`:`<div style="margin-top:24px">${empty('file','첫 기출 PDF를 등록해 보세요','학년과 회차별로 파일을 모으고, 원본을 보면서 한 문제씩 풀 수 있어요.',button('기출 PDF 등록','import-pdf','primary','upload'))}</div>`}<div class="panel help-copy" style="margin-top:24px"><h3 style="margin-top:0">기출을 나의 학습으로 바꾸는 3단계</h3><p>1. 공식 자료실에서 원하는 학년과 회차의 PDF를 내려받아요.<br>2. PDF와 정답표를 등록하고 원본을 보며 답안을 작성해요.<br>3. 필요한 문항은 ‘문제 등록’으로 입력해 개념과 연결하고 맞춤 학습지에 담아요.</p><p style="font-size:10px;margin-top:13px;color:#a0a88f">원본 PDF의 문항·도형 자동 추출은 지원하지 않습니다. 학습지에는 직접 등록한 텍스트 문항과 창작 연습문제를 담을 수 있어요.</p></div>`;}
function examPage(id){const exam=state.exams.find(e=>e.id===id);if(!exam)return emptyPage('등록한 PDF를 찾을 수 없어요.','archive');const latest=latestAttempts(state.attempts);return `${intro(esc(exam.title),`${gradeLabel(exam.grade)} · ${esc(exam.year)}년 ${esc(exam.semester)}`,button('자료실','go','secondary','back','data-path="archive"'))}<div class="exam-layout"><div><div id="pdf-container" class="pdf-viewer" style="display:grid;place-items:center;color:#8e9a82">PDF를 불러오는 중이에요…</div><div class="button-row" style="margin-top:12px">${button('원본 PDF 다운로드','download-exam','secondary small','download',`data-id="${esc(id)}"`)}${button('새 창에서 열기 / 인쇄','print-exam','secondary small','external',`data-id="${esc(id)}"`)}</div><p class="muted" style="font-size:10px;margin-top:9px">PDF가 표시되지 않는 모바일 브라우저에서는 다운로드하거나 새 창에서 열어 주세요.</p></div><aside class="panel"><div><h3 style="font-size:15px">문제별 답안</h3><p class="muted" style="font-size:11px;margin-top:6px">번호를 고른 뒤 원본에서 확인하세요.</p><div class="answer-grid">${Array.from({length:exam.count},(_,i)=>{const last=latest.get(`${id}:${i}`);return `<button class="${i===examIndex?'active':''} ${last?last.correct?'correct':'wrong':''}" data-action="exam-index" data-index="${i}" aria-label="${i+1}번 문제${last?last.correct?' 정답':' 오답':''}">${i+1}</button>`;}).join('')}</div></div><div class="exam-answer"><h4>${examIndex+1}번 문제</h4><form id="exam-answer" class="answer-form"><input name="answer" aria-label="${examIndex+1}번 답" placeholder="답을 적어 주세요" value="${esc(examDraft)}" autocomplete="off" ${exam.answers[examIndex]?'required':''}>${exam.answers[examIndex]?button('채점하기','exam-submit','primary','check','type="submit"'):`<p class="muted" style="font-size:10px">이 문항의 정답이 등록되지 않았어요.<br>정답지를 확인한 뒤 직접 기록해 주세요.</p><div class="button-row">${button('맞았어요','exam-self-correct','secondary','check','type="button"')}${button('다시 볼래요','exam-self-wrong','secondary','review','type="button"')}</div>`}</form>${examResult?`<div class="result ${examResult.correct?'':'wrong'}" style="padding:15px" role="status"><h3 style="font-size:13px">${examResult.correct?'잘 풀었어요!':'복습할 문제로 기록했어요.'}</h3><p style="font-size:11px">${exam.answers[examIndex]?`정답: ${esc(exam.answers[examIndex])}`:'스스로 채점한 기록이에요.'}</p></div>`:''}${examIndex<exam.count-1?button('다음 문제','exam-next','soft','arrow'):''}</div></aside></div>`;}
function selectedQuestions(){return state.selected.map(getQuestion).filter(Boolean);}
function worksheetPage(){const list=selectedQuestions();return `${intro('지금 필요한 문제만, 나만의 학습지','문제를 골라 한 권으로 만들고, 종이 위에서 생각을 펼쳐 보세요.')}<div class="worksheet-layout"><div class="worksheet-preview"><div class="paper"><div class="paper-head"><div class="paper-brand">THINK MATH · 생각수학</div><h2 id="paper-title">${esc(worksheet.title)}</h2><div class="paper-meta">이름: ______________　날짜: ______________　${list.length}문제</div></div>${list.length?list.map((q,i)=>`<div class="paper-question"><h3>${i+1}. ${esc(q.title)}</h3><p>${q.origin==='hme'?'공식 원문의 도형과 수식을 PDF에 포함합니다.':esc(q.text)}</p><div class="paper-space" style="height:${worksheet.space==='wide'?130:65}px"></div><div class="paper-answer">답: ____________________</div></div>`).join(''):`<div style="padding:50px 0;text-align:center"><span class="muted">아직 담은 문제가 없어요.</span><p class="muted" style="font-size:11px;margin:12px 0 20px">문제 목록에서 체크하거나<br>아래 버튼으로 현재 학년의 연습문제를 담아 보세요.</p>${button(`${gradeLabel(state.grade)} 문제 담기`,'select-grade','secondary','plus')}</div>`}</div></div><aside class="panel worksheet-controls"><h3 style="font-size:15px;margin-bottom:22px">학습지 설정</h3><label class="field"><span>학습지 제목</span><input id="worksheet-title" value="${esc(worksheet.title)}" maxlength="35" placeholder="학습지 제목"></label><label class="field"><span>풀이 공간</span><select id="worksheet-space"><option value="normal" ${worksheet.space==='normal'?'selected':''}>기본 공간</option><option value="wide" ${worksheet.space==='wide'?'selected':''}>넉넉한 공간</option></select></label><label class="checkbox-field"><input id="worksheet-answers" type="checkbox" ${worksheet.includeAnswers?'checked':''}>마지막에 정답과 풀이 포함</label><p class="muted" style="font-size:10px;margin-bottom:17px">A4 크기 · 한글 지원 · 문제와 정답 분리</p>${button('PDF 다운로드','export-pdf','primary','download',list.length?'':'disabled')}${button('학습지 인쇄','print-worksheet','secondary','printer',list.length?'':'disabled')}${button('문제 더 담기','go','ghost','plus','data-path="questions"')}<div style="margin-top:20px"><div class="section-heading"><h3 style="font-size:12px">담은 문제 ${list.length}개</h3>${list.length?'<button class="text-button" data-action="clear-selected">비우기</button>':''}</div>${list.map(q=>`<div class="selected-chip"><span>${esc(q.title)}</span><button data-action="remove-selected" data-id="${esc(q.id)}" aria-label="${esc(q.title)} 학습지에서 빼기">${icon('close')}</button></div>`).join('')}</div></aside></div>`;}
async function loadExam(id,seq){
 try{const file=await getFile(id);if(seq!==renderSequence)return;const container=document.querySelector('#pdf-container');if(!container)return;
 if(!file){container.innerHTML='<p style="padding:25px;text-align:center">원본 파일을 찾지 못했어요.<br>이 파일을 등록했던 브라우저에서 열거나 PDF를 다시 등록해 주세요.</p>';return;}
 if(!pdfLibraryPromise)pdfLibraryPromise=import('./vendor/pdfjs/pdf.min.mjs');
 const pdfjs=await pdfLibraryPromise;pdfjs.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdfjs/pdf.worker.min.mjs',import.meta.url).href;
 if(pdfId!==id||!activePdf){
   if(activePdf)await activePdf.destroy();
   const base=new URL('./vendor/pdfjs/',import.meta.url).href;
   activePdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),cMapUrl:base+'cmaps/',cMapPacked:true,standardFontDataUrl:base+'standard_fonts/',wasmUrl:base+'wasm/',isEvalSupported:false,enableXfa:false}).promise;
   pdfId=id;pdfPage=1;pdfZoom=1;
 }
 if(seq!==renderSequence)return;
 container.style.display='block';container.style.placeItems='normal';container.style.overflow='auto';
 container.innerHTML=`<div class="pdf-toolbar"><button class="icon-button" data-action="pdf-prev" aria-label="PDF 이전 페이지">${icon('back')}</button><span id="pdf-page-label"></span><button class="icon-button" data-action="pdf-next" aria-label="PDF 다음 페이지">${icon('arrow')}</button><span class="pdf-toolbar-spacer"></span><button class="icon-button" data-action="pdf-out" aria-label="PDF 축소">−</button><span id="pdf-zoom-label">100%</span><button class="icon-button" data-action="pdf-in" aria-label="PDF 확대">+</button></div><div class="pdf-canvas-wrap"><canvas id="pdf-canvas" aria-label="기출문제 원본 PDF 페이지"></canvas></div>`;
 await renderPdfPage();
 }catch(error){if(seq===renderSequence){const c=document.querySelector('#pdf-container');if(c)c.textContent=error.message;}}
}
async function renderPdfPage(){
 const canvas=document.querySelector('#pdf-canvas');if(!canvas||!activePdf)return;
 if(pdfRenderTask){pdfRenderTask.cancel();pdfRenderTask=null;}
 const current=activePdf;const pageNumber=pdfPage;
 const page=await current.getPage(pageNumber);if(current!==activePdf||!canvas.isConnected)return;
 const raw=page.getViewport({scale:1});const width=canvas.parentElement.clientWidth-32;const scale=Math.max(.3,width/raw.width)*pdfZoom;
 const viewport=page.getViewport({scale});const pixelRatio=Math.min(devicePixelRatio||1,2);
 canvas.width=Math.round(viewport.width*pixelRatio);canvas.height=Math.round(viewport.height*pixelRatio);canvas.style.width=viewport.width+'px';canvas.style.height=viewport.height+'px';
 document.querySelector('#pdf-page-label').textContent=`${pageNumber} / ${current.numPages}`;
 document.querySelector('#pdf-zoom-label').textContent=`${Math.round(pdfZoom*100)}%`;
 document.querySelector('[data-action="pdf-prev"]').disabled=pageNumber<=1;document.querySelector('[data-action="pdf-next"]').disabled=pageNumber>=current.numPages;
 try{pdfRenderTask=page.render({canvasContext:canvas.getContext('2d'),viewport,transform:pixelRatio===1?null:[pixelRatio,0,0,pixelRatio,0,0]});await pdfRenderTask.promise;}catch(error){if(error.name!=='RenderingCancelledException')toast('이 페이지를 표시하지 못했어요. 원본 다운로드로 확인해 주세요.');}
}
function render({keepScroll=false}={}){const position=scrollY;renderSequence++;const r=route();let content;switch(r.page){case 'home':content=home();break;case 'concepts':content=concepts();break;case 'lesson':content=lessonPage(r.id);break;case 'questions':content=questionsPage();break;case 'solve':content=solvePage(r.id);break;case 'review':content=reviewPage();break;case 'archive':content=archivePage();break;case 'exam':content=examPage(r.id);break;case 'worksheet':content=worksheetPage();break;case 'hme':content=hmePaperPage(r.id);break;case 'answers':content=hmePaperPage(r.id,true);break;case 'hme-document':content=hmeDocumentPage(r.id);break;default:content=emptyPage('페이지를 찾을 수 없어요.');}app.innerHTML=shell(content);document.title=`${r.page==='home'?'개념부터 탄탄하게':({concepts:'개념 학습',lesson:'개념 이해하기',questions:'문제 풀기',solve:'문제 풀이',review:'나의 오답노트',archive:'기출 자료실',exam:'기출 PDF 학습',worksheet:'학습지 만들기',hme:'기출 전체 문제 풀기',answers:'채점 결과·공식 해설집','hme-document':'공식 원문 여러 쪽'}[r.page]||'학습 홈')} · 생각수학`;if(!keepScroll)window.scrollTo(0,0);else window.scrollTo(0,position);scheduleHmeViews(renderSequence);if(['hme','answers','hme-document'].includes(r.page))paperFlow.mount(r.id);else paperFlow.dispose();if(r.page==='exam')loadExam(r.id,renderSequence);else if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=null;}}
function record(questionId,answer,correct,extra={}){rememberOfficial(getQuestion(questionId));state.attempts.push({questionId,answer,correct,day:localDay(),at:new Date().toISOString(),...extra});save();}
function closeModal(){modalRoot.innerHTML='';document.body.style.overflow='';returnFocus?.focus();}
function showModal(title,content,wide=false){returnFocus=document.activeElement;modalRoot.innerHTML=`<div class="modal-backdrop" data-overlay><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="닫기">${icon('close')}</button></div>${content}</section></div>`;document.body.style.overflow='hidden';requestAnimationFrame(()=>modalRoot.querySelector('input:not([type=file]),select,button')?.focus());}
const gradeOptions=()=>GRADES.map((g,i)=>`<option value="${i+1}" ${state.grade===i+1?'selected':''}>${g}</option>`).join('');
function importModal(){showModal('나의 기출 PDF 등록',`<p class="modal-description">공식 자료실에서 받은 원본을 등록하세요. 파일은 현재 브라우저에 저장되며, 서버로 전송하지 않아요.</p><form id="import-form"><label class="upload-zone">${icon('upload')}<p>기출문제 PDF를 선택해 주세요</p><small>PDF 파일 · 최대 30 MB</small><input name="pdf" id="pdf-upload" type="file" accept="application/pdf,.pdf" required></label><div class="form-grid"><label class="field span2"><span>자료 제목</span><input name="title" required maxlength="80" placeholder="예: HME 2025년 하반기 초등 4학년"></label><label class="field"><span>학년</span><select name="grade">${gradeOptions()}</select></label><label class="field"><span>시행 연도</span><input name="year" type="number" min="2000" max="2100" value="${new Date().getFullYear()}" required></label><label class="field"><span>회차</span><select name="semester"><option>상반기</option><option>하반기</option><option>기타</option></select></label><label class="field"><span>문제 수</span><input name="count" type="number" value="25" min="1" max="100" required></label><label class="field span2"><span>정답표 (선택)</span><textarea name="answers" placeholder="문제 번호 순서대로 한 줄에 한 답씩 입력하세요.&#10;15&#10;3/4&#10;8&#10;모르는 답은 - 로 표시해 주세요."></textarea><small>한 줄 = 한 문항. 미등록 문항은 스스로 채점할 수 있어요.</small></label></div><div class="button-row" style="justify-content:flex-end">${button('취소','close-modal','secondary','','type="button"')}${button('PDF 등록하기','import-submit','primary','upload','type="submit"')}</div></form>`);}
function customModal(){showModal('학습할 문제 등록',`<p class="modal-description">기출의 필요한 문항을 직접 입력하거나 나만의 문제를 만들어요. 등록한 문제는 온라인 채점과 학습지 PDF에 사용할 수 있어요. 현재는 텍스트 문항을 지원해요.</p><form id="custom-form"><div class="form-grid"><label class="field span2"><span>문제 제목</span><input name="title" required maxlength="80" placeholder="예: HME 2025 하반기 5번 · 분수의 덧셈"></label><label class="field"><span>학년</span><select name="grade">${gradeOptions()}</select></label><label class="field"><span>연결할 개념</span><select name="lesson">${LESSONS.map(l=>`<option value="${l.id}">${l.title}</option>`).join('')}</select></label><label class="field span2"><span>문제 내용</span><textarea name="text" required maxlength="2500" placeholder="조건과 질문을 빠짐없이 입력해 주세요."></textarea></label><label class="field"><span>정답</span><input name="answer" required maxlength="100" placeholder="예: 15 또는 3/4"></label><label class="field"><span>난이도</span><select name="difficulty"><option value="1">기본</option><option value="2" selected>도전</option><option value="3">심화</option></select></label><label class="field span2"><span>힌트 (선택)</span><input name="hint" maxlength="300" placeholder="어떤 원리를 떠올리면 좋을까요?"></label><label class="field span2"><span>단계별 해설 (선택)</span><textarea name="steps" maxlength="5000" placeholder="한 줄에 한 단계씩 적어 주세요."></textarea></label></div><div class="button-row" style="justify-content:flex-end">${button('취소','close-modal','secondary','','type="button"')}${button('문제 등록하기','custom-submit','primary','plus','type="submit"')}</div></form>`,true);}
function settingsModal(){showModal('나의 학습 설정',`<form id="settings-form"><label class="field"><span>불러 드릴 이름</span><input name="name" value="${esc(state.name)}" maxlength="20" required></label><label class="field"><span>학습 학년</span><select name="grade">${gradeOptions()}</select></label><label class="field"><span>하루 목표 문제 수</span><input name="dailyGoal" type="number" min="1" max="30" value="${state.dailyGoal}" required></label><p class="modal-description">풀이 기록과 등록한 문제는 이 기기의 브라우저에 저장돼요. 계정 동기화는 지원하지 않으며, 브라우저 데이터를 삭제하면 기록도 사라져요.</p><div class="button-row" style="justify-content:flex-end">${button('저장하기','save-settings','primary','check','type="submit"')}</div></form><div class="backup-tools">${button('학습 기록 내보내기','export-data','secondary','download')}</div><p class="muted" style="font-size:10px;margin-top:9px">JSON으로 풀이 기록과 직접 등록한 텍스트 문제를 저장해요. 원본 PDF 파일은 자료실에서 별도로 내려받으세요.</p>`);}
function helpModal(){showModal('생각수학 학습 가이드',`<div class="help-copy"><h3 style="margin-top:0">1. 원리를 먼저 이해해요</h3><p>개념 학습에서 예시와 단계별 설명을 읽고 확인 문제를 풀어요. 분수는 조각을 직접 눌러 보며 전체와 부분을 살펴볼 수 있어요.</p><h3>2. 스스로 풀고, 다시 생각해요</h3><p>학년을 고른 뒤 문제를 풀어 보세요. 생각 정리에 풀이를 적고 채점하면 해설이 나와요. 틀린 문제는 오답노트에 모이고, 다시 맞히면 해결한 문제로 옮겨져요.</p><h3>3. 기출 원본을 연결해요</h3><p>HME 공식 기출 탭에서 학년과 회차를 고르세요. 공식 정답표 대조가 완료된 문항은 원문을 보며 풀고 자동 채점할 수 있어요. 답을 제출한 뒤 공식 정답표와 풀이 원문을 함께 확인하세요. 정답 대조 대기 자료는 원문 학습으로 제공합니다. 직접 받은 PDF도 등록할 수 있어요.</p><h3>4. 나만의 학습지를 만들어요</h3><p>문제 목록의 체크 상자로 문항을 고른 뒤 학습지 만들기로 이동하세요. 제목과 풀이 공간, 해설 포함 여부를 정해 PDF로 내려받거나 인쇄할 수 있어요. 기출 문항은 ‘문제 등록’으로 입력해 담을 수 있어요.</p><h3>학습 기록 보관</h3><p>이 앱은 회원 가입 없이 이 브라우저에서 사용해요. 다른 기기와 동기화되지 않으므로 중요한 기록과 원본 PDF는 별도로 내려받아 보관해 주세요.</p></div>`);}
async function exportWorksheet(print=false){if(busy)return;const list=selectedQuestions();if(!list.length){toast('학습지에 담을 문제를 먼저 선택해 주세요.');return;}busy=true;const btn=document.querySelector(`[data-action="${print?'print-worksheet':'export-pdf'}"]`);if(btn){btn.disabled=true;btn.textContent='학습지를 만들고 있어요…';}try{const prepared=await Promise.all(list.map(async q=>q.origin==='hme'?{...q,image:await hmeQuestionRaster(q)}:q));const result=await makeWorksheet(prepared,worksheet);if(print)printPages(result.pages,worksheet.title);else downloadBlob(result.blob,safeFilename(worksheet.title)+'.pdf');toast(print?'인쇄 창에서 프린터와 용지를 확인해 주세요.':`${result.pages.length}쪽의 PDF 학습지를 만들었어요.`);}catch(error){console.error(error);toast('PDF를 만들지 못했어요. 브라우저를 새로고침하고 다시 시도해 주세요.');}finally{busy=false;render({keepScroll:true});}}
async function examFileAction(id,action){try{const file=await getFile(id);const exam=state.exams.find(e=>e.id===id);if(!file||!exam){toast('원본 파일이 없습니다. PDF를 다시 등록해 주세요.');return;}if(action==='download')downloadBlob(file,exam.filename);else{const url=URL.createObjectURL(file);const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.click();setTimeout(()=>URL.revokeObjectURL(url),120000);}}catch(error){toast(error.message);}}
function recordExam(correct){const e=state.exams.find(e=>e.id===route().id);if(!e)return;const answer=document.querySelector('#exam-answer input')?.value||examDraft;record(`${e.id}:${examIndex}`,answer,correct,{examId:e.id,index:examIndex,selfGraded:!e.answers[examIndex]});examResult={correct};examDraft=answer;render({keepScroll:true});}

document.addEventListener('click',async event=>{
 if(event.target.closest('.skip-link')){event.preventDefault();document.querySelector('#main')?.focus();return;}
 if(event.target.matches('[data-overlay]')){closeModal();return;}
 const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,id=b.dataset.id;
 switch(action){
 case 'go':if(b.dataset.path.startsWith('lesson/'))lessonResult=null;go(b.dataset.path);break;
 case 'menu':document.querySelector('.sidebar').classList.toggle('open');if(document.querySelector('.sidebar.open')){const shade=document.createElement('div');shade.className='sidebar-shade';shade.dataset.action='menu-close';document.body.append(shade);}break;
 case 'menu-close':document.querySelector('.sidebar')?.classList.remove('open');document.querySelector('.sidebar-shade')?.remove();break;
 case 'help':helpModal();break;case 'settings':settingsModal();break;case 'close-modal':closeModal();break;
 case 'search':filters.search='';go('questions');setTimeout(()=>document.querySelector('#question-search')?.focus(),30);break;
 case 'start':{if(currentCatalog()){startOfficial();break;}const latest=latestAttempts(state.attempts);const list=allQuestions().filter(q=>q.grade===state.grade);const q=list.find(q=>!latest.get(q.id)?.correct)||list[0];if(q)go(`solve/${q.id}`);else go('questions');break;}
 case 'lesson-practice':filters={search:'',lesson:id,difficulty:'all',status:'all'};go('questions');break;
 case 'status-filter':filters.status=id;render({keepScroll:true});break;
 case 'reset-filters':filters={search:'',lesson:'all',difficulty:'all',status:'all'};render({keepScroll:true});break;
 case 'bookmark':rememberOfficial(getQuestion(id));state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();render({keepScroll:true});break;
 case 'hint':captureStudy();studyUI.hint=!studyUI.hint;render({keepScroll:true});break;
 case 'retry':studyUI.result=null;studyUI.answer='';render({keepScroll:true});document.querySelector('#study-input')?.focus();break;
 case 'next-question':{const q=getQuestion(id);const list=allQuestions().filter(x=>x.grade===q.grade);const next=list[list.findIndex(x=>x.id===id)+1];if(next)go(`solve/${next.id}`);else{toast('이 학년의 마지막 문제까지 풀었어요!');go('home');}break;}
 case 'add-question':rememberOfficial(getQuestion(id));if(!state.selected.includes(id)){state.selected.push(id);save();toast('학습지에 문제를 담았어요.');}else toast('이미 학습지에 담은 문제예요.');break;
 case 'select-grade':state.selected=[...new Set([...state.selected,...allQuestions().filter(q=>q.grade===state.grade).map(q=>q.id)])];save();render({keepScroll:true});break;
 case 'clear-selected':state.selected=[];save();render({keepScroll:true});break;
 case 'remove-selected':state.selected=state.selected.filter(x=>x!==id);save();render({keepScroll:true});break;
 case 'fraction':b.classList.toggle('off');b.setAttribute('aria-pressed',String(!b.classList.contains('off')));document.querySelector('#fraction-display').textContent=`${document.querySelectorAll('#fraction-demo button:not(.off)').length} / 8`;break;
 case 'custom':customModal();break;case 'import-pdf':importModal();break;
 case 'open-exam':examIndex=0;examResult=null;examDraft='';go(`exam/${id}`);break;
 case 'exam-review':examIndex=Number(b.dataset.index);examResult=null;examDraft='';go(`exam/${id}`);break;
 case 'exam-index':examIndex=Number(b.dataset.index);examResult=null;examDraft='';render({keepScroll:true});break;
 case 'exam-next':{const e=state.exams.find(e=>e.id===route().id);if(examIndex<e.count-1)examIndex++;examResult=null;examDraft='';render({keepScroll:true});break;}
 case 'exam-self-correct':recordExam(true);break;case 'exam-self-wrong':recordExam(false);break;
 case 'download-exam':await examFileAction(id,'download');break;case 'print-exam':await examFileAction(id,'print');break;
 case 'pdf-prev':if(pdfPage>1){pdfPage--;await renderPdfPage();}break;
 case 'pdf-next':if(activePdf&&pdfPage<activePdf.numPages){pdfPage++;await renderPdfPage();}break;
 case 'pdf-in':pdfZoom=Math.min(2.5,pdfZoom+.25);await renderPdfPage();break;
 case 'pdf-out':pdfZoom=Math.max(.5,pdfZoom-.25);await renderPdfPage();break;
 case 'export-pdf':await exportWorksheet(false);break;case 'print-worksheet':await exportWorksheet(true);break;
 case 'export-data':downloadBlob(new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString(),note:'PDF files are stored separately in IndexedDB and are not included.'},null,2)],{type:'application/json'}),'생각수학-학습기록.json');toast('학습 기록을 내보냈어요. 원본 PDF는 별도로 보관해 주세요.');break;
 }
});
function captureStudy(){const input=document.querySelector('#study-input'),scratch=document.querySelector('#scratch');if(input)studyUI.answer=input.value;if(scratch)studyUI.scratch=scratch.value;}
document.addEventListener('change',event=>{const t=event.target;
 if(t.id==='global-grade'){state.grade=Number(t.value);save();if(['hme','answers','hme-document','archive'].includes(route().page))go('archive/1');else if(route().page==='questions'||route().page==='home')render({keepScroll:true});else toast(`${gradeLabel(state.grade)}으로 학년을 바꿨어요.`);}
 if(t.id==='filter-lesson'){filters.lesson=t.value;render({keepScroll:true});}
 if(t.id==='filter-difficulty'){filters.difficulty=t.value;render({keepScroll:true});}
 if(t.dataset.select){const id=t.dataset.select;if(t.checked)state.selected=[...new Set([...state.selected,id])];else state.selected=state.selected.filter(x=>x!==id);save();render({keepScroll:true});}
 if(t.id==='worksheet-space'){worksheet.space=t.value;render({keepScroll:true});}
 if(t.id==='worksheet-answers')worksheet.includeAnswers=t.checked;
 if(t.id==='pdf-upload' && t.files[0]){const title=modalRoot.querySelector('[name=title]');if(!title.value)title.value=t.files[0].name.replace(/\.pdf$/i,'');}
});
let searchTimer;
document.addEventListener('input',event=>{const t=event.target;
 if(t.id==='question-search'){clearTimeout(searchTimer);filters.search=t.value;searchTimer=setTimeout(()=>{if(route().page!=='questions')return;const start=t.selectionStart,end=t.selectionEnd;render({keepScroll:true});const node=document.querySelector('#question-search');node?.focus();if(node&&node.type!=='search')node.setSelectionRange(start,end);},200);}
 if(t.id==='worksheet-title'){worksheet.title=t.value;document.querySelector('#paper-title').textContent=t.value||'나만의 수학 학습지';}
 if(t.id==='scratch'||t.id==='study-input')captureStudy();
 if(t.closest('#exam-answer'))examDraft=t.value;
});
document.addEventListener('submit',async event=>{
 event.preventDefault();const form=event.target,data=new FormData(form);
 if(form.id==='study-answer'){captureStudy();const q=getQuestion(route().id);const answer=String(data.get('answer')).trim();if(!answer)return;if(q.origin==='hme'&&renderedHmeQuestion!==q.id)return;const correct=exactAnswer(answer,q.answer,q.answerType||'number');record(q.id,answer,correct);studyUI.result={correct,answer};render({keepScroll:true});}
 if(form.id==='lesson-answer'){const l=lessonById(route().id);const correct=isCorrect(data.get('answer'),l.check.answer);lessonResult={correct};if(correct&&!state.checkedLessons.includes(l.id)){state.checkedLessons.push(l.id);save();}render({keepScroll:true});}
 if(form.id==='exam-answer'){const e=state.exams.find(e=>e.id===route().id);if(e?.answers[examIndex])recordExam(isCorrect(data.get('answer'),e.answers[examIndex]));}
 if(form.id==='settings-form'){state.name=String(data.get('name')).trim()||'도전자';state.grade=Number(data.get('grade'));state.dailyGoal=Number(data.get('dailyGoal'));save();closeModal();render({keepScroll:true});toast('나의 학습 설정을 저장했어요.');}
 if(form.id==='custom-form'){
   const q={id:'custom-'+crypto.randomUUID(),grade:Number(data.get('grade')),lesson:String(data.get('lesson')),title:String(data.get('title')).trim(),text:String(data.get('text')).trim(),answer:String(data.get('answer')).trim(),hint:String(data.get('hint')).trim(),steps:String(data.get('steps')).split('\n').map(x=>x.trim()).filter(Boolean),difficulty:Number(data.get('difficulty')),origin:'registered',unit:''};
   if(!q.title||!q.text||!q.answer){toast('제목, 문제 내용, 정답을 입력해 주세요.');return;}state.custom.push(q);state.grade=q.grade;save();closeModal();filters={search:'',lesson:'all',difficulty:'all',status:'all'};go('questions');toast('문제를 등록했어요. 온라인 풀이와 학습지에 사용할 수 있어요.');
 }
 if(form.id==='import-form'){
   const file=data.get('pdf');if(!(file instanceof File)||!file.size){toast('PDF 파일을 선택해 주세요.');return;}if(file.size>30*1024*1024){toast('30 MB 이하의 PDF를 등록해 주세요.');return;}
   const signature=new TextDecoder().decode(await file.slice(0,1024).arrayBuffer());if(!signature.includes('%PDF-')){toast('올바른 PDF 파일을 선택해 주세요.');return;}
   const title=String(data.get('title')).trim();const count=Number(data.get('count'));if(!title||!Number.isInteger(count)||count<1||count>100)return;
   const rawAnswers=String(data.get('answers')).trim();const lines=rawAnswers?rawAnswers.split(/\r?\n/).map(x=>x.trim()):[];if(lines.length>count){toast(`정답이 ${lines.length}개지만 문제 수는 ${count}개예요. 문제 수와 정답표를 확인해 주세요.`);return;}
   const exam={id:'exam-'+crypto.randomUUID(),title,grade:Number(data.get('grade')),year:Number(data.get('year')),semester:String(data.get('semester')),count,answers:Array.from({length:count},(_,i)=>lines[i]&&lines[i]!=='-'?lines[i]:null),filename:file.name,createdAt:new Date().toISOString()};
   const submit=form.querySelector('[type=submit]');submit.disabled=true;submit.textContent='파일을 저장하고 있어요…';
   try{await putFile(exam.id,file);state.exams.push(exam);save();closeModal();go('archive');toast('기출 PDF를 등록했어요. 이제 온라인에서 풀어 보세요.');}catch(error){toast(error.message||'PDF 저장에 실패했어요.');submit.disabled=false;submit.textContent='PDF 등록하기';}
 }
});
document.addEventListener('keydown',event=>{if(!modalRoot.children.length)return;if(event.key==='Escape'){closeModal();return;}if(event.key==='Tab'){const nodes=[...modalRoot.querySelectorAll('button,input,select,textarea,a[href]')].filter(n=>!n.disabled);const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{clearTimeout(searchTimer);document.querySelector('.sidebar-shade')?.remove();closeModal();lessonResult=null;if(route().page==='solve')studyUI.id=null;render();});
function rememberOfficial(q){if(q?.origin!=='hme')return;state.officialCache||=[];if(!state.officialCache.some(x=>x.id===q.id))state.officialCache.push(q);}
function requestOfficialPaper(id){if(hmeRequests.has(id)||getCachedHmePaper(id))return;hmeRequests.add(id);loadHmePaper(id).then(()=>render({keepScroll:true})).catch(error=>toast(error.message)).finally(()=>hmeRequests.delete(id));}
function officialSummary(id){return currentCatalog()?.papers.find(p=>p.id===id);}
function officialChoice(grade=state.grade){return currentCatalog()?.papers.find(p=>p.grade===grade&&p.onlineCount>0);}
function hmeOriginTabs(){return `<div class="filter-tabs hme-origin-switch"><button data-action="bank-origin" data-id="hme" class="${bankOrigin==='hme'?'active':''}">HME 공식 기출</button><button data-action="bank-origin" data-id="created" class="${bankOrigin==='created'?'active':''}">창작·직접 등록 문제</button></div>`;}
function questionsPage(){
 if(bankOrigin==='created')return hmeOriginTabs()+practiceQuestionsPage();
 const catalog=currentCatalog();if(!catalog)return `${intro('공식 기출문제를 불러오고 있어요','문제지와 공식 풀이지를 연결하는 중입니다.')}<div class="source-loading">회차 목록을 불러오는 중…</div>${hmeOriginTabs()}`;
 const list=catalog.papers.filter(p=>p.grade===state.grade&&p.onlineCount>0);
 if(!list.some(p=>p.id===bankPaperId))bankPaperId=list[0]?.id||'';
 const paper=getCachedHmePaper(bankPaperId);if(bankPaperId&&!paper)requestOfficialPaper(bankPaperId);
 const questions=(paper?.questions||[]).filter(q=>filters.lesson==='all'||q.lesson===filters.lesson).filter(q=>!filters.search||`${q.title} ${q.text}`.includes(filters.search));
 return `${intro('공식 기출로, 한 문제씩 확실하게',`${gradeLabel(state.grade)} · 정답표 대조를 마친 기출문제`,button('기출 전체 보기','go','secondary','file','data-path="archive"'))}${hmeOriginTabs()}<div class="toolbar"><select id="hme-bank-paper" class="field-control" aria-label="기출 회차">${list.map(p=>`<option value="${p.id}" ${p.id===bankPaperId?'selected':''}>${p.year}년 ${p.semester} · ${p.onlineCount}문항</option>`).join('')}</select><label class="search-box">${icon('search')}<input type="search" id="question-search" aria-label="문제 검색" value="${esc(filters.search)}" placeholder="문제 내용이나 개념 검색"></label><select class="field-control" id="filter-lesson" aria-label="개념 필터"><option value="all">모든 개념</option>${LESSONS.map(l=>`<option value="${l.id}" ${filters.lesson===l.id?'selected':''}>${l.title}</option>`).join('')}</select></div><div class="official-banner">${icon('check')}<div><strong>공식 풀이지의 문항 번호와 정답을 대조했어요.</strong><br>도형과 수식은 원문 그대로 확인하고, 답을 제출한 뒤 공식 풀이를 펼쳐 보세요.</div></div><div class="list-meta"><span>선택 회차 <strong>${questions.length}</strong>문항</span><button class="text-button" data-action="go" data-path="worksheet">학습지에 담은 문제 ${state.selected.length}개 ${icon('printer')}</button></div><div class="question-list">${paper?questions.length?questions.map(q=>questionRow(q)).join(''):empty('search','선택한 조건에 맞는 문제가 없어요.','필터를 바꾸거나 다른 회차를 선택해 주세요.'): '<div class="source-loading">문항을 불러오고 있어요…</div>'}</div>`;
}
function archivePage(){
 const catalog=currentCatalog();if(!catalog)return '<div class="source-loading">공식 기출 자료실을 불러오는 중이에요…</div>';
 const papers=catalog.papers.filter(p=>p.grade===state.grade).filter(p=>hmeYear==='all'||String(p.year)===hmeYear).filter(p=>!hmeOnlyChecked||p.onlineCount>0);
 const years=[...new Set(catalog.papers.filter(p=>p.grade===state.grade).map(p=>p.year))].sort((a,b)=>b-a);
 const pagination=paginate(papers,route().id,8);
 const pageLink=(n,label)=>'<a href="#archive/'+n+'" '+(pagination.page===n?'aria-current="page"':'')+'>'+label+'</a>';
 return intro('HME 공식 기출 자료실','학년과 연도를 고르고, 문제를 순서대로 풀어 답안을 제출하세요.',button('내 PDF 등록','import-pdf','secondary','upload'))+
 '<div class="hme-summary"><div><strong>'+catalog.papers.length+'</strong>문제지·풀이지 쌍</div><div><strong>'+catalog.questionCount.toLocaleString()+'</strong>온라인 문항</div><div><strong>3단계</strong>기출 선택 → 문제 풀기 → 해설집</div></div>'+
 '<div class="paper-filter-bar archive-filter-bar"><label>학년 선택<select id="archive-grade" aria-label="자료실 학년">'+GRADES.map((g,i)=>'<option value="'+(i+1)+'" '+(state.grade===i+1?'selected':'')+'>'+g+'</option>').join('')+'</select></label><label>연도 선택<select id="hme-year" aria-label="기출 연도"><option value="all">모든 연도</option>'+years.map(y=>'<option value="'+y+'" '+(hmeYear===String(y)?'selected':'')+'>'+y+'년</option>').join('')+'</select></label></div>'+
 '<div class="list-meta"><label class="checkbox-field"><input type="checkbox" id="hme-checked-only" '+(hmeOnlyChecked?'checked':'')+'>온라인으로 풀 수 있는 회차만</label><span>'+papers.length+'개 회차 · '+pagination.page+' / '+pagination.pages+'페이지</span></div>'+
 '<div class="archive-paper-list">'+(pagination.items.length?pagination.items.map(p=>'<article class="archive-paper-row"><div class="paper-row-icon">HME</div><div class="paper-row-copy"><div class="tags">'+tag(gradeLabel(p.grade),'gray')+tag(p.onlineCount>0?'공식 정답표 대조':'정답 대조 대기',p.onlineCount>0?'':'peach')+'</div><h2>'+p.year+'년 '+p.semester+' · '+gradeLabel(p.grade)+'</h2><p>'+(p.onlineCount>0?'문제 '+p.onlineCount+'개를 위에서 아래로 풀고, 답안 제출 후 공식 해설집을 확인해요.':'정답 대조 대기 자료 · 저장된 문제지와 해설집으로 학습해요.')+'</p></div><div class="button-row">'+button(p.onlineCount>0?'전체 문제 풀기':'원문 공부하기','go','primary small','arrow','data-path="'+(p.onlineCount>0?'hme':'hme-document')+'/'+p.id+'"')+button('원문 여러 쪽','go','secondary small','file','data-path="hme-document/'+p.id+'"')+'</div></article>').join(''):empty('search','선택한 학년·연도의 자료가 없어요.','다른 연도나 학년을 선택해 주세요.'))+'</div>'+
 '<nav class="archive-pagination" aria-label="자료실 페이지">'+(pagination.page>1?pageLink(pagination.page-1,'이전'):'')+Array.from({length:pagination.pages},(_,i)=>pageLink(i+1,i+1)).join('')+(pagination.page<pagination.pages?pageLink(pagination.page+1,'다음'):'')+'</nav>'+
 '<div class="notice">'+icon('info')+'<span>공식 정답표와 대조한 문항만 자동 채점해요. 대조 대기 자료도 앱에 저장된 문제지와 해설집으로 공부할 수 있어요. 원본 수집일 '+esc(catalog.retrievedAt)+'</span></div>'+
 (state.exams.length?'<div class="section-heading" style="margin-top:30px"><h2>직접 등록한 PDF</h2></div><div class="exam-grid">'+state.exams.map(x=>'<article class="exam-card">'+tag('직접 등록','gray')+'<h3>'+esc(x.title)+'</h3><p>'+gradeLabel(x.grade)+' · '+x.count+'문제</p>'+button('학습 시작','open-exam','secondary','arrow','data-id="'+x.id+'"')+'</article>').join('')+'</div>':'');
}
function hmePaperPage(id,answers=false){
 const summary=officialSummary(id);if(!summary)return emptyPage('기출 회차를 찾을 수 없어요.','archive');
 const paper=getCachedHmePaper(id);if(!paper){requestOfficialPaper(id);return '<div class="source-loading">공식 문항과 정답표를 불러오는 중…</div>';}
 if(!paper.questions.length)return hmeDocumentPage(id);
 if(state.grade!==paper.grade){state.grade=paper.grade;save();}
 return paperFlow.page(paper,answers);
}
function solvePage(id){
 if(/^hme-\d+-[1-9]-q\d+$/.test(id)&&!getCachedHmePaper(id.replace(/-q\d+$/,''))){requestOfficialPaper(id.replace(/-q\d+$/,''));return '<div class="source-loading">최신 공식 문항과 정답표를 확인하는 중…</div>';}
 const q=getQuestion(id);if(q?.origin!=='hme'){
   if(/^hme-\d+-[1-9]-q\d+$/.test(id)&&!q){requestOfficialPaper(id.replace(/-q\d+$/,''));return '<div class="source-loading">기출 문항을 불러오는 중…</div>';}
   return practiceSolvePage(id);
 }
 if(studyUI.id!==id)studyUI={id,hint:false,result:null,answer:'',scratch:'',reveal:false};
 renderedHmeQuestion=null;
 const result=studyUI.result,showSolution=!!result||studyUI.reveal;
 return `${button('회차의 문제 목록','go','ghost hme-back','back',`data-path="hme/${q.examId}"`)}<div class="hme-pair-grid"><article class="panel question-panel"><div class="question-top"><div class="tags">${tag('HME 공식 기출')}${tag(gradeLabel(q.grade),'gray')}${tag(`${q.number}번`,'peach')}</div><span class="question-number">${q.year} ${q.semester}</span></div><h2>${q.year}년 ${q.semester} · ${q.number}번 문제</h2><p class="muted" style="font-size:11px">초록색 테두리의 ${q.number}번을 풀어 보세요. 공통 지문과 도형도 원본 페이지에서 함께 확인할 수 있어요.</p><div class="source-viewer"><div class="source-caption"><span>공식 문제지 · ${q.paperPage}쪽</span><button type="button" data-action="hme-download" data-file="${esc(q.paper)}" class="text-button">원본 PDF 내려받기 ${icon('download')}</button></div><div class="source-scroll"><canvas data-hme-source="${esc(q.paper)}" data-page="${q.paperPage}" data-highlight="${esc(JSON.stringify(q.paperClip))}" data-question="${q.id}" aria-label="공식 원문 ${q.number}번 문제와 공통 도형"></canvas><div class="source-loading">검증된 원문을 불러오는 중…</div></div></div>${q.answerType==='choice'?`<div class="hme-choices" role="group" aria-label="객관식 답 선택">${['①','②','③','④','⑤'].map((v,i)=>`<button data-action="hme-choice" data-value="${i+1}" class="${studyUI.answer===String(i+1)?'active':''}">${v}</button>`).join('')}</div>`:''}<label class="field-label" for="scratch">나의 풀이</label><textarea id="scratch" class="work-area" placeholder="사용한 원리와 계산 과정을 적어 보세요.">${esc(studyUI.scratch)}</textarea><form id="study-answer" class="answer-form"><label for="study-input">나의 답</label><input id="study-input" name="answer" value="${esc(studyUI.answer)}" placeholder="${q.answerType==='choice'?'선택 번호 (1~5)':'숫자 또는 분수로 답을 입력하세요'}" required autocomplete="off">${button('공식 답안으로 채점','submit-answer','primary','check','type="submit" data-hme-grade disabled')}</form><p class="verification-note">공식 정답표와 문항 번호를 대조한 답으로 채점해요.</p><div class="button-row">${button('학습지에 담기','add-question','secondary small','plus',`data-id="${q.id}"`)}${button('공식 정답·풀이 확인','hme-reveal','ghost small','book')}</div>${result?`<div class="result ${result.correct?'':'wrong'}" role="status"><h3>${result.correct?'정답이에요! 공식 답안과 일치해요.':'공식 답안과 달라요. 풀이를 함께 확인해요.'}</h3><p>내 답: ${esc(result.answer)}　·　공식 정답: <strong>${esc(q.answerDisplay)}</strong></p><div class="button-row" style="margin-top:15px">${button('다음 기출문제','hme-next-question','primary small','arrow',`data-id="${q.id}"`)}${button('다시 풀기','retry','secondary small','review')}</div></div>`:''}${showSolution?`<section class="official-result"><h3 style="font-size:16px">공식 정답표와 풀이 원문</h3><p class="muted" style="font-size:11px;margin-top:7px">이 문항의 공식 정답은 ${esc(q.answerDisplay)}입니다. 문제 번호 ${q.number}번을 원문 정답표에서 직접 대조해 보세요.</p><div class="official-key"><canvas data-hme-source="${esc(q.solution)}" data-page="${q.keyPage}" data-clip="${esc(JSON.stringify(q.keyClip))}" aria-label="공식 정답표 원본"></canvas><div class="source-loading">공식 정답표를 불러오는 중…</div></div><div class="source-viewer"><div class="source-caption"><span>공식 풀이지 · ${q.solutionPage}쪽부터</span><button class="text-button" data-action="go" data-path="hme-document/${q.examId}">전체 풀이·다음 쪽 보기 ${icon('external')}</button></div><div class="source-scroll"><canvas data-hme-source="${esc(q.solution)}" data-page="${q.solutionPage}" aria-label="공식 정답과 해설 원문 페이지"></canvas><div class="source-loading">공식 풀이를 불러오는 중…</div></div></div></section>`:''}</article><aside class="study-side"><div class="aside-card"><span class="concept-icon mint">${icon('file')}</span><h3>공식 자료를 직접 확인해요</h3><p>${q.year}년 ${q.semester}<br>${gradeLabel(q.grade)} · ${q.number}번<br>공식 정답표 대조 완료</p><p class="hme-file-label">${esc(q.paper)}<br>${esc(q.solution)}</p><a class="btn secondary" href="${SOURCE_URL}" target="_blank" rel="noopener noreferrer">HME 공식 출처 ${icon('external')}</a></div><div class="aside-card"><h3>원리부터 다시 살펴보기</h3><p>이 문제에 연결할 수 있는 개념을 참고하고, 문제의 조건에 맞게 적용해 보세요.</p>${button(lessonById(q.lesson).title,'go','secondary','book',`data-path="lesson/${q.lesson}"`)}</div></aside></div>`;
}
function hmeDocumentPage(id){
 const summary=officialSummary(id);if(!summary)return emptyPage('기출 원문을 찾을 수 없어요.','archive');
 const paper=getCachedHmePaper(id);if(!paper){requestOfficialPaper(id);return '<div class="source-loading">저장된 기출 자료를 불러오는 중…</div>';}
 const note=paper.questions.length?'':'<div class="notice">저장된 문제지와 공식 해설집을 바로 볼 수 있어요. 이 회차는 정답 대조가 끝나지 않아 자동 채점을 제공하지 않습니다.</div>';
 return note+paperFlow.documentPage(paper,hmeDocKind);
}

async function scheduleHmeViews(seq){
 for(const container of document.querySelectorAll('.source-viewer')){if(container.querySelector('canvas[data-hme-source]'))container.insertAdjacentHTML('beforeend',`<div class="source-zoom"><span>원문 확대 · 좌우로 이동</span><button data-action="hme-zoom-out" aria-label="원문 축소">−</button><span>${Math.round(hmeZoom*100)}%</span><button data-action="hme-zoom-in" aria-label="원문 확대">+</button></div>`);}
 for(const canvas of document.querySelectorAll('canvas[data-hme-source]')){
   try{const question=getQuestion(route().id);const sourceHeight=canvas.dataset.hmeSource===question?.paper?question.paperDimensions?.[1]:canvas.dataset.hmeSource===question?.solution?question.solutionDimensions?.[1]:null;const result=await drawHmePage(canvas,canvas.dataset.hmeSource,Number(canvas.dataset.page),{clip:canvas.dataset.clip?JSON.parse(canvas.dataset.clip):null,highlight:canvas.dataset.highlight?JSON.parse(canvas.dataset.highlight):null,sourceHeight,zoom:canvas.dataset.clip?1:hmeZoom});
     if(seq!==renderSequence||!canvas.isConnected)continue;canvas.nextElementSibling?.remove();
     if(canvas.dataset.question){renderedHmeQuestion=canvas.dataset.question;document.querySelector('[data-hme-grade]')?.removeAttribute('disabled');}
     if(canvas.dataset.document){hmeDocPages=result.pages;const label=document.querySelector('#hme-doc-page');if(label)label.textContent=`${result.page} / ${result.pages}쪽`;const next=document.querySelector('[data-action="hme-doc-next"]');if(next)next.disabled=result.page>=result.pages;}
   }catch(error){if(seq!==renderSequence||!canvas.isConnected)continue;canvas.hidden=true;const note=canvas.nextElementSibling;if(note){note.className='source-error';note.textContent='공식 원본을 불러오지 못했어요. 원본이 변경됐거나 연결이 지연될 수 있습니다. 다시 열어 확인해 주세요.';}console.error('HME source load failed',error);}
 }
}
async function startOfficial(){const p=officialChoice();if(!p){go('questions');return;}try{const data=await loadHmePaper(p.id);const latest=latestAttempts(state.attempts);const q=data.questions.find(q=>!latest.get(q.id)?.correct)||data.questions[0];go(`solve/${q.id}`);}catch(error){toast(error.message);}}
document.addEventListener('click',async event=>{
 const b=event.target.closest('[data-action]');if(!b||b.disabled)return;
 switch(b.dataset.action){
 case 'bank-origin':bankOrigin=b.dataset.id;filters.search='';filters.lesson='all';render();break;
 case 'hme-more':hmeLimit+=12;render({keepScroll:true});break;
 case 'hme-zoom-in':hmeZoom=Math.min(3,hmeZoom+.5);render({keepScroll:true});break;
 case 'hme-zoom-out':hmeZoom=Math.max(.5,hmeZoom-.5);render({keepScroll:true});break;
 case 'hme-choice':studyUI.answer=b.dataset.value;document.querySelector('#study-input').value=b.dataset.value;document.querySelectorAll('.hme-choices button').forEach(n=>n.classList.toggle('active',n===b));break;
 case 'hme-reveal':captureStudy();studyUI.reveal=true;render({keepScroll:true});break;
 case 'hme-next-question':{const q=getQuestion(b.dataset.id);const p=await loadHmePaper(q.examId);const next=p.questions.find(x=>x.number>q.number);go(next?`solve/${next.id}`:`hme/${q.examId}`);break;}
 case 'hme-doc-kind':hmeDocKind=b.dataset.kind;hmeDocPage=1;render({keepScroll:true});break;
 case 'hme-doc-prev':if(hmeDocPage>1)hmeDocPage--;render({keepScroll:true});break;
 case 'hme-doc-next':if(hmeDocPage<hmeDocPages)hmeDocPage++;render({keepScroll:true});break;
 case 'hme-select-paper':{const p=await loadHmePaper(b.dataset.id);p.questions.forEach(rememberOfficial);state.selected=[...new Set([...state.selected,...p.questions.map(q=>q.id)])];save();toast(`${p.questions.length}문제를 학습지에 담았어요.`);break;}
 case 'hme-download':try{const bytes=await getHmeBytes(b.dataset.file);downloadBlob(new Blob([bytes],{type:'application/pdf'}),b.dataset.file);}catch{toast('공식 원본을 내려받지 못했습니다. 잠시 후 다시 시도해 주세요.');}break;
 }
});
document.addEventListener('change',event=>{const t=event.target;
 if(t.id==='hme-bank-paper'){bankPaperId=t.value;filters.search='';filters.lesson='all';render();}
 if(t.id==='hme-year'){hmeYear=t.value;go('archive/1');}
 if(t.id==='hme-checked-only'){hmeOnlyChecked=t.checked;go('archive/1');}
 if(t.id==='archive-grade'){state.grade=Number(t.value);save();if(hmeYear!=='all'&&!currentCatalog().papers.some(p=>p.grade===state.grade&&String(p.year)===hmeYear))hmeYear='all';go('archive/1');}
 if(t.dataset.select){const q=getQuestion(t.dataset.select);if(q?.origin==='hme'){rememberOfficial(q);save();}}
});
const paperFlow=createPaperStudy({state:()=>state,save,go,render:()=>render({keepScroll:true}),grade:grade=>{state.grade=grade;save();},graded:(paper,result,submission)=>{for(const row of result.rows){if(row.correct===null)continue;rememberOfficial(paper.questions.find(q=>q.id===row.id));state.attempts.push({questionId:row.id,answer:row.answer,correct:row.correct,day:localDay(),at:submission.at,paperSubmission:submission.id});}save();}});
render();
loadHmeCatalog().then(()=>render({keepScroll:true})).catch(()=>{bankOrigin='created';if(route().page==='questions')render();});
